#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
uniform float2 amzVelocity,amzPivot,amzScale;
uniform float amzAngularVelocity,amzScaleVelocity,amzStartTime,amzEndTime;

struct AC_ImageInfo { int texture; float2 amzLocal_size; };
const float3x3 labPlaneInverse=float3x3(1);
float4x4 amzQuaternion(float4 q) {
    q /= max(length(q),0.000001);
    float x=q.x,y=q.y,z=q.z,w=q.w;
    return float4x4(1-2*(y*y+z*z),2*(x*y+w*z),2*(x*z-w*y),0,
                    2*(x*y-w*z),1-2*(x*x+z*z),2*(y*z+w*x),0,
                    2*(x*z+w*y),2*(y*z-w*x),1-2*(x*x+y*y),0,0,0,0,1);
}
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
float4 amzTexture(int tex,float2 uv,float bias){return amzTexture(tex,uv);}
uniform float amzp_posx;
uniform float amzp_posy;
uniform float amzp_posz;
uniform float amzp_angle;
uniform float amzp_alpha;
uniform float amzp_scale;
uniform float amzp_anglea;
uniform float amzp_pinch;
uniform float2 amzp_centerPoint;
uniform float amzp_strength;
uniform float amzp_radius;
uniform float amzp_satriyhaid;
uniform float amzp_start;
uniform float amzp_end;
uniform float amzp_angleb;
uniform float amzp_feather;
layout(color) uniform half4 amzp_color;
uniform float amzp_alphaa;
uniform float amzp_blendMode;
uniform float amzp_zinv;
uniform float amzp_xinv;
uniform float amzp_yinv;
uniform float amzp_ainv;





        float2 project(float2 a, float2 b) {
            return (dot(a,b)/dot(b,b)) * b;
        }

        float smoothstepRev(float edge0, float edge1, float x) {
            if(edge0 == edge1) return step(edge0, x);
            else return smoothstep(edge0, edge1, x);
        }

        void amzRender() {
            float adjStart = amzp_start;
            float adjEnd = amzp_end;
            float adjFeather = amzp_feather/100.0;
            float radwipe = amzp_angleb * 0.0174533;
            float2 v = normalize(float2(cos(radwipe),-sin(radwipe)));


            float p = dot(amzLayerNorm().st-float2(0.5,0.5), v)+0.5;

            float p0 = smoothstepRev(adjStart-adjFeather,adjStart,p);
            float p1 = 1. - smoothstepRev(adjEnd,adjEnd+adjFeather,p);

            float rad = amzp_anglea* 0.0174533;
            float2x2 rot = float2x2(cos(rad),-sin(rad),sin(rad),cos(rad));
            float2x2 invrot = float2x2(cos(-rad),-sin(-rad),sin(-rad),cos(-rad));

            float2 sampleCoord = ((((amzLayerNorm() - 0.5) * rot) * float2((1.0/amzp_scale), 1.0)) * invrot) + 0.5;
            sampleCoord = (float4(sampleCoord,0.0,1.0) * amzLayerToScreen()).xy;


            if ( (amzp_pinch>0.5) ) {
            float2 center = (amzLayerCenter()/screen.zw)-(amzp_centerPoint/1000. * float2(-1.,1.));

            sampleCoord -= center;
            sampleCoord.x *= screen.zw.x / screen.zw.y;
            float dist = length(sampleCoord);
            if ( dist < amzp_radius ) {
                float p = dist / amzp_radius;
                if(amzp_strength > 0.) {
                    sampleCoord *= mix(1.0, smoothstep(0.0, amzp_radius / dist, p), amzp_strength * 0.75);
                } else {
                    sampleCoord *= mix(1.0, pow(p, 1.0 + amzp_strength * 0.75) * amzp_radius / dist, 1.0 - p);
                }
            }
            sampleCoord.x /= screen.zw.x / screen.zw.y;
            sampleCoord += center;
            }


            float4 texColor;
            if( (amzp_satriyhaid>0.5) ) {
            texColor = amzTexture(0,sampleCoord) *p0*p1*amzp_alpha;
            } else {
            texColor = amzTexture(0,sampleCoord) * amzp_alpha;
            }

            float4 result;
            if( int(amzp_blendMode)==1 ) {
                result = float4((texColor.rgb/texColor.a)*amzp_color.rgb,1.0) * texColor.a;
            } else if( int(amzp_blendMode)==2 ) {
                result = float4( 1.-((1.-(texColor.rgb/texColor.a))*(1.-amzp_color.rgb)),1.0) * texColor.a;
            } else {
                result = float4(amzp_color.rgb,1.0)*texColor.a;
            }
            amzOutput = mix(texColor,result,amzp_alphaa);
        }


half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

legacyScript:
function animate(env,el,p) {
    let t = env.time;
    var xposition = p.posx;
    if ( p.xinv ) {
    xposition = xposition * -1;
    }
    var zposition = p.posz;
    if ( p.zinv ) {
    zposition = 1.0 + (1.0 - zposition);
    }
    var yposition = p.posy;
    if ( p.yinv ) {
    yposition = yposition * -1;
    }
    var aposition = p.angle;
    if ( p.ainv ) {
    aposition = aposition * -1;
    }
    el.transform.location.x += xposition;
    el.transform.location.y += yposition;
    el.transform.angle += aposition;
    el.transform.scale.x += zposition-1;
    el.transform.scale.y += zposition-1;
    return el;
}

